<h2>Estimates</h2>
<?php if (! ($b22Ready ?? false)): ?><p>Estimate/document schema is incomplete. B2.2 actions require the approved migration.</p>
<?php else: ?>
<p><a href="<?= $base ?>/estimates/new">Add estimate</a> · <a href="<?= $base ?>/documents/new">Add document</a></p>
<?php if ($estimates === []): ?><p>No repair estimate recorded.</p><?php endif; ?>
<?php foreach ($estimates as $estimate): $estimateId = (int) $estimate['id']; $validity = \App\Services\Fleet\VehicleDamageRepairEstimateService::validity($estimate); ?>
<article class="section" style="overflow-wrap:anywhere"><h3><?= $estimate['status_code'] === 'accepted' ? 'Accepted estimate' : 'Estimate' ?> <?= esc($estimate['currency']) ?> <?= esc($estimate['amount']) ?></h3>
<p><strong><?= esc(ucfirst($estimate['status_code'])) ?></strong> · <?= $estimate['recording_mode'] === 'historical_incomplete' ? 'Historical estimate — source details incomplete' : 'Authoritative source recorded' ?> · <?= $validity === 'expired' ? 'Expired' : ($validity === 'unknown' ? 'Expiry unknown' : 'Valid') ?></p>
<p>Vendor: <?= esc($estimate['vendor_snapshot'] ?? 'Unknown / not recorded') ?> · Quote date: <?= esc($estimate['quote_date'] ?? 'Unknown / not recorded') ?> · Expiry: <?= esc($estimate['expires_at'] ?? $estimate['expires_on'] ?? 'Unknown') ?></p>
<p>Series <?= esc($estimate['quote_series_key']) ?> · Revision <?= (int) $estimate['revision_number'] ?> · Reference <?= esc($estimate['vendor_quote_reference'] ?? 'Not recorded') ?></p>
<?php foreach (['note', 'historical_recording_reason'] as $field): if ($estimate[$field] !== null): ?><p><?= nl2br(esc($estimate[$field])) ?></p><?php endif; endforeach; ?>
<h4>Frozen scope (one quoted total)</h4><ul><?php foreach ($estimateScopes as $scope): if ((int) $scope['vehicle_damage_repair_estimate_id'] !== $estimateId) { continue; } $snapshot = json_decode($scope['condition_snapshot'], true); $currentMember = array_values(array_filter($members, static fn ($m) => (int) $m['id'] === (int) $scope['vehicle_damage_repair_job_item_id']))[0] ?? null; ?><li><?= esc($snapshot['description']) ?> · <?= esc($snapshot['zone']) ?> · <?= esc($snapshot['panel'] ?? 'Panel unknown') ?> · <?= esc($snapshot['damage_type']) ?> · <?= esc($snapshot['severity']) ?> · <?= esc($snapshot['physical_status']) ?><?php if ($currentMember === null || $currentMember['withdrawn_at'] !== null): ?> · Current membership withdrawn<?php endif; ?></li><?php endforeach; ?></ul>
<h4>Source documents</h4><?php $quoteSources = array_values(array_filter($repairDocuments, static fn ($d) => (int) $d['vehicle_damage_repair_estimate_id'] === $estimateId)); $activeSourceCount = count(array_filter($quoteSources, static fn ($d) => $d['archived_at'] === null && $d['kind_code'] === 'estimate' && $d['external_reference'] === null)); ?><p>Active binary estimate sources: <?= $activeSourceCount ?><?= $activeSourceCount === 0 ? ' - New acceptance requires an available active source.' : '' ?></p><ul><?php foreach ($quoteSources as $source): ?><li><?= esc($source['label'] ?? $source['content_original_filename'] ?? 'External reference') ?><?= $source['archived_at'] === null ? '' : ' - Archived' ?><?php if ($source['external_reference'] === null): ?> &middot; <a href="<?= $base ?>/documents/<?= (int) $source['id'] ?>/download">Download source</a><?php else: ?> &middot; <?= esc($source['external_reference']) ?><?php endif; ?></li><?php endforeach; ?></ul>
<p><a href="<?= $base ?>/estimates/<?= $estimateId ?>/revision">Record new revision</a></p>
<?php foreach (['accept' => 'Accept estimate', 'reject' => 'Reject estimate', 'withdraw' => 'Withdraw estimate'] as $action => $label): if (($action === 'accept' && ($estimate['status_code'] !== 'received' || $estimate['recording_mode'] !== 'current_quote' || $validity === 'expired' || $activeSourceCount === 0 || $terminal || $job['intent_code'] !== 'repair')) || ($action === 'reject' && $estimate['status_code'] !== 'received') || ($action === 'withdraw' && ! in_array($estimate['status_code'], ['received', 'accepted'], true))) { continue; } ?>
<details class="capital-disclosure"><summary><?= esc($label) ?></summary><form action="<?= $base ?>/estimates/<?= $estimateId ?>/<?= $action ?>" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'estimate_' . $action . '_' . $estimateId]) ?><input type="hidden" name="expected_estimate_state" value="<?= esc($estimateStates[$estimateId], 'attr') ?>">
<?php if ($action === 'accept' && $job['accepted_estimate_id'] !== null): ?><input type="hidden" name="previous_accepted_estimate_id" value="<?= (int) $job['accepted_estimate_id'] ?>"><input type="hidden" name="expected_previous_accepted_state" value="<?= esc($estimateStates[$job['accepted_estimate_id']], 'attr') ?>"><p>Replaces the current accepted quote. A different series withdraws the prior selection; the same series supersedes it.</p><?php endif; ?>
<label>Decision reason<textarea name="reason" maxlength="2000" <?= $action !== 'accept' || $job['accepted_estimate_id'] !== null ? 'required' : '' ?>></textarea></label><label><input type="checkbox" name="confirmed" value="1" required> I reviewed this quote, its current scope, sources, and selection.</label><button type="submit"><?= esc($label) ?></button></form></details><?php endforeach; ?></article><?php endforeach; ?>
<h2>Documents</h2><?php if ($repairDocuments === []): ?><p>No repair document recorded.</p><?php endif; ?>
<?php foreach ($repairDocuments as $document): $documentId = (int) $document['id']; ?><article class="section" style="overflow-wrap:anywhere"><h3><?= esc(\Config\VehicleDamageRepairDocuments::KINDS[$document['kind_code']]) ?> · <?= esc($document['label'] ?? $document['content_original_filename'] ?? 'External reference') ?></h3>
<p>Estimate <?= $document['vehicle_damage_repair_estimate_id'] === null ? 'Not linked' : (int) $document['vehicle_damage_repair_estimate_id'] ?> · Membership <?= $document['vehicle_damage_repair_job_item_id'] === null ? 'Not linked' : (int) $document['vehicle_damage_repair_job_item_id'] ?></p>
<?php if ($document['external_reference'] !== null): ?><p><?= esc($document['external_reference']) ?></p><?php else: ?><p><a href="<?= $base ?>/documents/<?= $documentId ?>/download">Download private document</a></p><?php endif; ?>
<?php if ($document['note'] !== null): ?><p><?= nl2br(esc($document['note'])) ?></p><?php endif; ?>
<?php if ($document['archived_at'] !== null): ?><p><strong>Archived</strong> <?= esc($document['archived_at']) ?> · <?= esc($document['archive_reason']) ?></p><?php else: ?><details class="capital-disclosure"><summary>Archive document</summary><form action="<?= $base ?>/documents/<?= $documentId ?>/archive" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'document_archive_' . $documentId]) ?><input type="hidden" name="expected_document_state" value="<?= esc($documentStates[$documentId], 'attr') ?>"><label>Archive reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="1" required> Retain this document in history and remove it from new acceptance support.</label><button type="submit">Archive document</button></form></details><?php endif; ?></article><?php endforeach; ?>
<?php endif; ?>
